package com.securevault.service;
import com.securevault.entity.*;import com.securevault.repository.*;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;
@Service public class SecurityMonitoringService{
 private final SecurityEventRepository events;private final DeviceRepository devices;private final NotificationService notifications;private final UserSessionRepository sessions;private final AnalyticsCacheService cache;
 public SecurityMonitoringService(SecurityEventRepository e,DeviceRepository d,NotificationService n,UserSessionRepository s,AnalyticsCacheService c){events=e;devices=d;notifications=n;sessions=s;cache=c;}
 public SecurityEvent recordLogin(User u,String status,String ip,String device,String browser,String details){SecurityEvent e=record(u,"LOGIN",status,ip,details);e.setDevice(device);e.setBrowser(browser);return events.save(e);}
 public SecurityEvent record(User u,String type,String status,String ip,String details){SecurityEvent e=new SecurityEvent();e.setUser(u);e.setEventType(type);e.setStatus(status);e.setIpAddress(ip);e.setDetails(details);long fails=events.countByUserAndStatusAndCreatedAtBetween(u,"FAILED",LocalDateTime.now().minusMinutes(15),LocalDateTime.now());if("LOGIN".equals(type)&&"FAILED".equals(status)&&fails>=4){e.setSuspicious(true);e.setRiskLevel("HIGH");notifications.create(u,"RISK","Suspicious login activity","Multiple failed login attempts were detected.");}else if("LOGIN".equals(type)&&"FAILED".equals(status)){e.setRiskLevel("MEDIUM");}return events.save(e);}
 public List<SecurityEvent> events(User u,LocalDateTime a,LocalDateTime b){return events.findByUserAndCreatedAtBetweenOrderByCreatedAtDesc(u,a,b);}public List<Device> deviceList(User u){return devices.findByUserOrderByLastSeenDesc(u);}
 public Map<String,Object> analytics(User u,LocalDateTime a,LocalDateTime b){String key="analytics:"+u.getId()+":"+a.toLocalDate()+":"+b.toLocalDate();List<SecurityEvent> list=events(u,a,b);long success=list.stream().filter(e->"SUCCESS".equals(e.getStatus())).count();long failed=list.stream().filter(e->"FAILED".equals(e.getStatus())).count();long suspicious=list.stream().filter(SecurityEvent::isSuspicious).count();long alerts=list.stream().filter(e->"OPEN".equals(e.getStatus())||"ALERT".equals(e.getEventType())).count();Map<String,Object> m=new LinkedHashMap<>();m.put("successfulLogins",success);m.put("failedLogins",failed);m.put("suspiciousActivities",suspicious);m.put("activeAlerts",alerts);m.put("recentSecurityActivity",list.stream().limit(10).toList());cache.put(key,success+","+failed+","+suspicious+","+alerts);return m;}
}
